<?php

namespace Database\Seeders;

use App\Models\PartnerProfile;
use App\Models\User;
use Illuminate\Database\Seeder;

class PartnerSeeder extends Seeder
{
    public function run(): void
    {
        $companies = [
            'Сбер',
            'Тинькофф',
            'Яндекс',
            'Ростех',
            'Лукойл',
            'Газпром',
            'Роснефть',
            'МТС',
            'Мегафон',
            'VK',
            'Ростелеком',
            'Альфа-Банк',
            'X5 Retail Group',
            'Магнит',
            'Wildberries',
        ];

        $partners = User::role('partner')->orderBy('id')->get();

        if ($partners->isEmpty()) {
            return;
        }

        foreach ($partners as $index => $partner) {
            $companyName = $companies[$index % count($companies)];

            $description = $this->getDescription($companyName);
            $website = $this->getWebsite($companyName);

            $profile = $partner->partnerProfile ?? new PartnerProfile;
            $profile->fill([
                'user_id' => $partner->id,
                'company_name' => $companyName,
                'description' => $description,
                'website' => $website,
                'is_active' => true,
            ])->save();
        }
    }

